-- What production holds that the production-shaped copy lacks, for 090's merge (SELECT 1/11, pg_get_constraintdef /
-- pg_get_triggerdef / prosrc verbatim): the 25 foreign keys onto locations and clients of consolidated_loads,
-- groupage_lines and pallet_ledger_suppliers (the copy holds the other 72), and the two order-leg triggers that copy a
-- parent's places to its legs and a leg's hand-over to its sibling (order_parent_to_legs / order_legs_to_parent, with
-- order_legs_audit). plan-090.test.mjs proves md5(prosrc) = production's.
-- pallet_ledger_suppliers is not in the copy's catalog snapshot: its id and the two columns 090 moves
CREATE TABLE IF NOT EXISTS public.pallet_ledger_suppliers (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY);
ALTER TABLE public.pallet_ledger_suppliers ADD COLUMN IF NOT EXISTS loading_supplier_id bigint, ADD COLUMN IF NOT EXISTS client_id bigint;
ALTER TABLE consolidated_loads ADD CONSTRAINT consolidated_loads_client_id_fkey FOREIGN KEY (client_id) REFERENCES clients(id);
